select su.id, username, su.name, type, phone, avatar_url, additional_info, post_id, su.status, sp.name post_name from system_user su left join system_post sp on su.post_id = sp.id and sp.is_deleted = 0 su.is_deleted = 0 and su.status = 1 and su.name like concat('%',#{queryVo.name},'%')
and su.phone like concat('%',#{queryVo.phone},'%')
and su.post_id = #{queryVo.postId}
